$HOME/.codex/hooks.json.text:
{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "command": "other-start",
            "custom": true
          }
        ]
      },
      {
        "hooks": [
          {
            "command": "pacer status --hook codex",
            "timeout": 15,
            "type": "command",
            "statusMessage": "Checking subscription budgets"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "spawn_agent",
        "hooks": [
          {
            "command": "other-guard"
          }
        ]
      },
      {
        "matcher": "spawn_agent",
        "hooks": [
          {
            "command": "pacer guard --planner codex",
            "timeout": 15,
            "type": "command"
          }
        ]
      }
    ]
  }
}
